import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom sklearn.model_selection import train_test_splitfrom sklearn.preprocessing import StandardScalerfrom sklearn.preprocessing import LabelEncoderfrom sklearn.svm import SVCfrom matplotlib.colors import ListedColormapfrom sklearn.metrics import accuracy_scorefrom sklearn.model_selection import GridSearchCV### I need to do a grid search firstparam_grid = {'C': [0.1, 1, 10, 100, 1000, 10000], 			'gamma': [1, 0.1, 0.01, 0.001, 0.0001, 0.00001], 			'kernel': ['rbf']} model_performance = pd.DataFrame()for clusterx in tqdm(range(0,26)):    if clusterx in [14,18,21] :        continue        base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs/cluster_"    path = f"{base_path}{clusterx}.csv"    cluster_data = pd.read_csv(path)        # set up training data    training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]    training_labels = np.where(training_data['Status']=='M', 0, 1)    training_matrix = training_data.iloc[:,3:].to_numpy()        svm_base = SVC()        grid_search = GridSearchCV(            estimator=svm_base,            param_grid=param_grid,            cv=5,            scoring='accuracy')            grid_search.fit(training_matrix, training_labels)            best_model = grid_search.best_estimator_    best_c = grid_search.best_params_['C']    best_gamma = grid_search.best_params_['gamma']    best_score = grid_search.best_score_                   data_to_bind = pd.DataFrame({           'cluster': [clusterx],           'best_C': [best_c],           'best_gamma':[best_gamma],           'cv_score': [best_score]           })    model_performance = pd.concat([model_performance, data_to_bind], ignore_index=True)#alright we are gonna have to do a big boy for loopsvm_data = pd.DataFrame()for clusterx in (range(0,26)):    if clusterx in [14,18,21] :        continue        base_path = "/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/degs/cluster_"    path = f"{base_path}{clusterx}.csv"    cluster_data = pd.read_csv(path)        # set up training data    training_data = cluster_data[cluster_data['Status'].isin(['M','F'])]    training_labels = np.where(training_data['Status']=='M', 0, 1)    training_matrix = training_data.iloc[:,3:].to_numpy()        # set up test data    test_data = cluster_data[cluster_data['Status'].isin(['D'])]    test_matrix = test_data.iloc[:,3:].to_numpy()        # scale data    scaler = StandardScaler()    scaler.fit(training_matrix)    train_std_x = scaler.transform(training_matrix)    test_std_x = scaler.transform(test_matrix)        #run SVM    optimal_c = model_performance['best_C'][model_performance['cluster']==clusterx].iloc[0]    optimal_gamma = model_performance['best_gamma'][model_performance['cluster']==clusterx].iloc[0]    svm = SVC(kernel = 'rbf',               C = optimal_c,                random_state = 1,              gamma=optimal_gamma)         svm.fit(train_std_x, training_labels)        #predict    predictions = svm.predict(test_std_x)        print(f"cluster {clusterx} {predictions.mean()}")        mean_probability_female = predictions.mean() # i wonder if I can include each individual as a row, for now I wont though        data_to_bind = pd.DataFrame({'cluster' : [clusterx],                                    'C':[optimal_c],                                    'gamma':[optimal_gamma],                                    'mean_probability_female' : [mean_probability_female]})        svm_data = pd.concat([svm_data, data_to_bind], ignore_index=True)        svm_data.to_csv("/Users/ggraham/Desktop/multiome_poa/Sex Classifier and Linearity/progress_classifier/initial_svm_predictions_06_11_2025.csv") svm_data['mean_probability_female'].hist(bins =5)                